/* com.lsy.sicore_v1.code.mapper.CodeMapper.insertCode 코드 등록 */
INSERT INTO TB_CODE
(
      CODE
    , GROUP_CODE
    , CODE_NAME
    , SORT_ORDER
    , CREATED_AT
    , UPDATED_AT
)
VALUES
(
      #{code}
    , #{groupCode}
    , #{codeName}
    , #{sortOrder}
    , SYSDATE
    , SYSDATE
)

mapper.update:
/* com.lsy.sicore_v1.code.mapper.CodeMapper.updateCode 코드 수정 */ UPDATE TB_CODE
CODE = #{codeVo.code},
GROUP_CODE = #{codeVo.groupCode},
CODE_NAME = #{codeVo.codeName},
SORT_ORDER = #{codeVo.sortOrder},
GROUP_CODE = #{oldGroupCode} AND CODE = #{oldCode}

/* com.lsy.sicore_v1.code.mapper.CodeMapper.deleteCode 코드 사용 중지 */
UPDATE TB_CODE
   SET USE_YN = 'N'
   WHERE GROUP_CODE = #{groupCode} AND CODE = #{code}
